import{_ as t,o,c as a,ae as s}from"./chunks/framework.DQC_QtFV.js";const u=JSON.parse('{"title":"First start and QR login","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/first-start.md","filePath":"en/guide/first-start.md","lastUpdated":1793162416000}'),r={name:"en/guide/first-start.md"};function n(i,e,d,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="first-start-and-qr-login" tabindex="-1">First start and QR login <a class="header-anchor" href="#first-start-and-qr-login" aria-label="Permalink to &quot;First start and QR login&quot;">​</a></h1><p>No image contains QQ. On its first start the <code>qq</code> container installs the pinned build from <strong>exactly one</strong> of two sources:</p><table tabindex="0"><thead><tr><th>Source</th><th>How to give it</th></tr></thead><tbody><tr><td>A download URL</td><td><code>QQ_DEB_URL=https://example.com/QQ_3.2.34_260924_amd64_01.deb</code> in <code>.env</code></td></tr><tr><td>A deb you already have</td><td>mount it at <code>/qq/QQ.deb</code> in <code>compose.yaml</code> (two lines to uncomment) and leave <code>QQ_DEB_URL</code> empty</td></tr></tbody></table><p>Either way the container verifies the file&#39;s sha256 against the pin baked into the image and <strong>refuses to install anything else</strong>, with an error that names the version it expected. The install lands in the <code>qq_install</code> volume, so later starts skip it. If you give neither source, or both, the container says so and prints both options rather than guessing.</p><div class="warning custom-block"><p class="custom-block-title">The official download URL answers 403</p><p>The official URL does not serve the file without a signature. Download it from a mirror, check its sha256 yourself, then either serve it locally (<code>python3 -m http.server</code> plus <code>QQ_DEB_URL=http://127.0.0.1:8000/&lt;file&gt;</code>, with <code>network_mode: host</code> for the install step) or mount it as a file.</p></div><h2 id="qr-login" tabindex="-1">QR login <a class="header-anchor" href="#qr-login" aria-label="Permalink to &quot;QR login&quot;">​</a></h2><ol><li>After <code>docker compose up -d</code>, open <a href="http://localhost:8080" target="_blank" rel="noreferrer">http://localhost:8080</a> and sign in with <code>CONSOLE_PASSWORD</code>.</li><li>The panel&#39;s QQ page (the live view) is the client&#39;s own screen. When the QR code appears, scan it with the phone app. <strong>The scan is manual and yours to do</strong> - it is the only login step that needs you.</li><li>Tick 自动登录 so later restarts resume without scanning.</li><li>Once the scan succeeds, the driver reads the database key and the status line&#39;s <code>db.key</code> turns to <code>&quot;ok&quot;</code>.</li></ol><p>When the client returns to its account page after a restart, the driver clicks 登录 by itself and the saved session resumes; the 登录 button on the panel&#39;s QQ page is the manual retry for that step. A new scan is needed only after the profile has been recreated (the <code>qq_profile</code> volume removed).</p><h2 id="the-key-extraction" tabindex="-1">The key extraction <a class="header-anchor" href="#the-key-extraction" aria-label="Permalink to &quot;The key extraction&quot;">​</a></h2><p>The key lets the stack decrypt a <strong>private copy</strong> of the client&#39;s own database - message ids, senders, mentions, quotes and images all come from that copy, and no file of the client is patched, replaced or written to. The key stays on your machine: <code>data/driver/secrets/db_key</code>, mode 0600.</p><p>It is extracted once, on first login, and stays valid across restarts. A status of <code>db.key = &quot;missing&quot;</code> means it has not finished; the log is <code>./logs/keyx.log</code> on the host. A status of <code>&quot;invalid&quot;</code> means the client changed its key or the copy no longer matches; follow the re-extract steps on the QQ page.</p><h2 id="when-something-is-wrong" tabindex="-1">When something is wrong <a class="header-anchor" href="#when-something-is-wrong" aria-label="Permalink to &quot;When something is wrong&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>What it means</th></tr></thead><tbody><tr><td><code>error: no QQ source: set exactly one of ...</code></td><td>neither <code>QQ_DEB_URL</code> nor a mounted deb was given</td></tr><tr><td><code>error: sha256 mismatch: expected ... got ...</code></td><td>the deb is not the pinned build; get the right file</td></tr><tr><td><code>error: both QQ_DEB_URL and the mounted deb ... are set</code></td><td>remove one of the two</td></tr><tr><td>The live view stays on the QR code</td><td>that is correct: a QR login is manual and yours to do</td></tr><tr><td>The panel&#39;s pages answer 502</td><td>the driver or the bot is not up yet; check <code>docker compose logs qq bot</code></td></tr></tbody></table><p>More in <a href="./troubleshooting.html">Troubleshooting</a>.</p>',14)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
